// Workers entry. Wraps OpenNext's worker and adds:
// - scheduled(): the daily safety-net sync (POST /api/internal/cron);
// - queue(): sync jobs enqueued by webhooks (POST /api/internal/sync each).
// Both go through OpenNext's fetch so they run in the same request context
// (env, Hyperdrive binding) as every HTTP request.
// @ts-expect-error generated by `opennextjs-cloudflare build`; resolved by wrangler's bundler.
import openNext from "../../.open-next/worker.js";

// The few Workers runtime types this entry needs (the Next app's tsconfig does
// not load @cloudflare/workers-types).
interface ExecutionContext {
  waitUntil(promise: Promise<unknown>): void;
  passThroughOnException(): void;
}
interface ScheduledEvent {
  cron: string;
  scheduledTime: number;
}

interface Env {
  CRON_SECRET: string;
  APP_BASE_URL?: string;
}

interface QueueMessage {
  body: unknown;
  ack: () => void;
  retry: () => void;
}

const base = (env: Env) => env.APP_BASE_URL ?? "https://fire.internal";

async function internal(path: string, body: unknown, env: Env, ctx: ExecutionContext): Promise<Response> {
  const req = new Request(`${base(env)}${path}`, {
    method: "POST",
    headers: { authorization: `Bearer ${env.CRON_SECRET}`, "content-type": "application/json" },
    body: JSON.stringify(body),
  });
  return openNext.fetch(req, env, ctx);
}

const worker = {
  fetch: openNext.fetch,

  async scheduled(_event: ScheduledEvent, env: Env, ctx: ExecutionContext): Promise<void> {
    const res = await internal("/api/internal/cron", {}, env, ctx);
    if (!res.ok) throw new Error(`cron failed: HTTP ${res.status}`);
  },

  async queue(batch: { messages: QueueMessage[] }, env: Env, ctx: ExecutionContext): Promise<void> {
    for (const msg of batch.messages) {
      const res = await internal("/api/internal/sync", msg.body, env, ctx);
      if (res.ok) msg.ack();
      else msg.retry();
    }
  },
};

export default worker;
